"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["91017"],{18889(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.passo_com_escala_de_atendimento","status":422,"titulo":"A etapa com escala de atendimento n\xe3o declara passo do lan\xe7amento"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.passo_com_escala_de_atendimento","requisitos":["UNI-REQ-0175"],"oQueAconteceu":["A etapa declarou `escalaDeAtendimento` e tamb\xe9m um `passoDoLancamento`. O passo \xe9 o\\nintervalo entre duas notas que um avaliador pode digitar (por exemplo, de 0,5 em 0,5).\\nCom a escala, o avaliador n\xe3o digita a nota: escolhe o n\xedvel de cada item, e o sistema\\ncalcula a pontua\xe7\xe3o a partir da fra\xe7\xe3o do n\xedvel. O passo n\xe3o teria a quem se aplicar.","A recusa vale j\xe1 na grava\xe7\xe3o, tamb\xe9m em rascunho, e chega no array `errors[]`, no campo\\n`passoDoLancamento` da etapa."],"comoResolver":["Escolha um dos dois caminhos:","- se a banca escolhe o n\xedvel de atendimento, remova o `passoDoLancamento`. Na forma\\n  `HUMANA`, o passo deixa de ser obrigat\xf3rio na publica\xe7\xe3o quando a etapa tem escala;\\n- se a banca digita a nota de cada item, remova a escala de atendimento e mantenha o\\n  passo.","Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de\\nreenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);